   [171]={next_id=172, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不，你很勇敢。一个人面对了寻常人无法面对的苦难，成为命星骑士，守卫维拉提亚，守护它的人民。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
